import {VERSION,STORAGE_KEY,STEPS,DATA,TRANSFER_DATA,backtest,PRACTICE,ASSESSMENTS,check,grade,freshState,restoreState,invalidate,labEvidence} from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),storageOK=true,page='start';try{state=restoreState(localStorage.getItem(STORAGE_KEY));}catch{storageOK=false;}
const value=id=>state.fields[id]||'',fmt=n=>n===null?'Undefined':Number(n).toFixed(3),field=(id,label,area=false,defaultValue='')=>`<label class="field" for="${id}">${label}</label>${area?`<textarea id="${id}" data-save>${esc(state.fields[id]??defaultValue)}</textarea>`:`<input id="${id}" data-save type="number" step="any" value="${esc(state.fields[id]??defaultValue)}">`}`,box=(id,label)=>`<label class="option"><input id="${id}" type="checkbox" data-save ${value(id)==='yes'?'checked':''}><span>${label}</span></label>`;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'Saved on this device':'Saving unavailable · export before leaving';nav();}
function nav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#progress-label').textContent=`${n} of 8 steps complete`;$('#progress-percent').textContent=Math.round(n/8*100)+'%';$('#progress').value=n;$('#navigation').innerHTML=STEPS.map(([id,t,m],i)=>`<a href="#${id}" ${id===page?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':i+1}</span><span>${t}<small>${m} min${state.done[id]?' · complete':''}</small></span></a>`).join('');}
function feedback(id,text,error=false){const el=$('#'+id);el.textContent=text;el.className='feedback'+(error?' error':'');el.tabIndex=-1;el.focus();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const table=(data=DATA)=>`<div class="table-wrap"><table><caption>Original synthetic ${data===DATA?'development':'transfer'} prices, pounds per unit. Dates label ordered teaching observations; weekends are intentional hypothetical sessions.</caption><thead><tr><th>Date</th><th>Open (£)</th><th>Close (£)</th></tr></thead><tbody>${data.map(r=>`<tr><th scope="row">${r.date}</th><td>${r.open}</td><td>${r.close}</td></tr>`).join('')}</tbody></table></div><p><a href="prices.csv" download>Development CSV</a> · <a href="transfer-prices.csv" download>Transfer CSV</a> · <a href="data-dictionary.md">Data dictionary</a></p>`;
const header=(title,lead)=>`<div class="eyebrow">CHAPTER 08 · ${STEPS.find(s=>s[0]===page)?.[2]} MINUTES</div><h1>${title}</h1><p class="lead">${lead}</p>`;
function start(){return header('Trace<br><em>every trade.</em>','A believable result needs a visible clock, every fee and a fair comparison. Implement one frozen rule before interpreting its performance.')+`<div class="pill-row"><span class="pill">180-minute core</span><span class="pill">No installation</span><span class="pill">Python optional +30min</span></div><section class="panel"><h2>Standalone learning setup</h2><p>Bring a calculator and paper. Prerequisites: percentages, compound wealth and a three-value mean. Warm up:(100+101+102)/3=101;1000×.999=999. No coding knowledge is needed. The browser and complete paper route provide worked examples, hints, transfer checks, feedback and revision.</p><p>Schedule:setup10;timing25;positions25;costs30;benchmark25;lab35;independent transfer20;evidence card10=180minutes. Estimates await learner testing; no countdown applies.</p><p><a href="guide.html">Complete text and paper route</a>. Local progress is chapter-specific. Export downloads answers, every check attempt, trial and revision; it is not import/sync. Never enter personal account details.</p>${box('setup','I found the data, calculator, complete text route, Export and Privacy & reset.')}<button data-action="setup">Confirm setup & continue</button><div id="feedback-start" class="feedback" role="status"></div></section><section class="panel"><h2>Freeze before running</h2><p>Rule:close strictly above trailing3-close mean →weight1;else0. Signal after close t;execute open t+1;earn open t+1→open t+2. Start£1000,cost10bps per traded notional,cash0%. No leverage,shorting,dividends,default,tax or additional slippage. Initial entry and final exit are included. Do not optimise this rule. Every run and cost sensitivity is retained.</p><p>Outcomes: trace this timeline; reproduce positions; calculate net wealth and final liquidation; match the buy-and-hold window; explain why a synthetic run cannot validate profitability.</p>${table()}</section>`;}
function practice(step){const l=LESSONS[step];return header(l.title,l.objective)+l.body+table()+`<section class="panel"><h2>Try, check, explain, revise</h2><p>Use a calculator. Enter numbers only: no % sign. Round to two decimals or keep more precision. Choice questions use the stated number.</p>${PRACTICE[step].map((q,i)=>`<div class="practice-item">${field(q.id,q.title)}<div class="actions"><button data-action="practice" data-id="${q.id}">Check task ${i+1}</button><details><summary>Hint</summary><p>${q.hint}</p></details></div><div id="feedback-${q.id}" class="feedback" role="status">${state.checked[q.id]?'Correct. '+q.hint:''}</div></div>`).join('')}<h3>Explain and revise</h3><p>${l.reflection}</p>${field(step+'Reflection','My explanation, check or correction',true)}${box(step+'Criteria',l.criteria)}<p class="mini">Self-review checks reasoning; the app checks numerical answers and that you supplied at least 30 characters. Prose quality is not automatically graded.</p><button data-action="save-step">Save this lesson</button><div id="feedback-step" class="feedback" role="status">${state.done[step]?'Lesson evidence saved.':''}</div></section>`;}
function runResult(run){const x=run.result;return `<h3>Frozen3-close rule,cost${run.cost}bps</h3><div class="result-grid"><p>Strategy final£${fmt(x.finalWealth)}<br>Net change${fmt(x.totalReturn*100)}%</p><p>Benchmark final£${fmt(x.benchmarkFinal)}<br>Net change${fmt(x.benchmarkReturn*100)}%</p></div><p>Final exit charges:strategy£${fmt(x.finalExitCost)},benchmark£${fmt(x.benchmarkExitCost)}. The final row below is before those liquidation charges. Benchmark and strategy eligible opens:Jan5→Jan17.</p><div class="table-wrap run-list"><table><caption>Complete execution ledger. Costs charged at entry before the interval return. Wealth is pounds; displayed values rounded only for reading.</caption><thead><tr><th>Signal close</th><th>Mean</th><th>Execute open</th><th>Mark open</th><th>Weight</th><th>Turnover</th><th>Gross underlying%</th><th>Start£</th><th>End£</th><th>Benchmark£</th></tr></thead><tbody>${x.rows.map(r=>`<tr><th scope="row">${r.signalDate}</th><td>${fmt(r.average)}</td><td>${r.entryDate}</td><td>${r.exitDate}</td><td>${r.position}</td><td>${r.turnover}</td><td>${fmt(r.grossReturn*100)}</td><td>${fmt(r.startWealth)}</td><td>${fmt(r.endWealth)}</td><td>${fmt(r.benchmarkEnd)}</td></tr>`).join('')}</tbody></table></div>`;}
function lab(){const r=state.runs.at(-1);return header('The rule stays fixed.','Change only the cost assumption, hand-check the first interval and retain both trials. A worse result is useful evidence.')+`<p>This is sensitivity analysis of a predefined rule, not a parameter search. Development data are already visible. The final card and Chapters9–10 must disclose this exposure and all trials. A trial on authored prices is not out-of-sample market validation.</p><section class="panel"><h2>Predict then calculate</h2>${field('prediction','Predict what increasing costs can do to final wealth when prices and positions stay fixed; give a reason (20+characters).',true)}${field('cost','Cost in basis points per traded notional (0–100)',false,'10')}<button data-action="run">Run fixed rule</button><div id="feedback-run" class="feedback" role="status"></div>${r?runResult(r):'<p>Your full execution ledger appears here.</p>'}</section><section class="panel"><h2>Hand-check and revise</h2><p>The first weight is1,entry103,nextopen100,initial£1000. Verify1000×(1−cost/10000)×100/103. Then change only costs (try10→30bps); keep all prices, timing and the window fixed. Do not select a nicer-looking cost after inspecting results.</p>${field('hand','Latest first interval end wealth before later exits (£)')}<button data-action="hand">Check my hand calculation</button><div id="feedback-hand" class="feedback" role="status">${value('handVerified')==='yes'?'Latest first interval checked.':''}</div>${field('labReflection','Compare both net strategy and benchmark wealth across costs, revise your prediction and name an execution limitation (50+characters).',true)}${box('labCriteria','I held the rule/data fixed, included final exits, matched eligible opens and avoided a profitability claim.')}<details><summary>Feedback criteria</summary><p>With these unchanged0/1positions and nonnegative fees,higher costs cannot improve final wealth. Both series pay entry/exit fees but turnover can differ. Verify every action against the ledger; a cash interval can still incur an exit charge. Missing slippage or realistic liquidity can make these results optimistic. The small synthetic series offers no market-edge evidence.</p></details><button data-action="save-lab">Save lab evidence</button><button data-action="csv" class="secondary">Export all execution ledgers CSV</button><div id="feedback-lab" class="feedback" role="status"></div></section><section class="panel"><h2>All trials retained</h2><ol>${state.runs.map(r=>`<li>${esc(r.time)};cost${r.cost}bps;strategy£${fmt(r.result.finalWealth)},benchmark£${fmt(r.result.benchmarkFinal)};prediction:${esc(r.prediction)}</li>`).join('')||'<li>No runs yet.</li>'}</ol></section>`;}
function assessment(){const a=state.attempts.at(-1);return header('Use a fresh case.','Independent transfer · Attempt all eight questions before checking. Then act on the feedback and resubmit if needed.')+`<section class="panel"><p>No countdown. Calculator and paper allowed. Work independently before revealing feedback. Pass: at least 7 of 8, including all critical model or timing conventions marked by the feedback. This is formative self-learning, not a secure exam or credential.</p>${table(TRANSFER_DATA)}${ASSESSMENTS.map(q=>field('quiz-'+q.id,q.title)).join('')}<button data-action="grade">Check independent attempt</button><div id="feedback-assessment" class="feedback" role="status">${a?`${a.score}/8 on last submitted attempt. ${a.passed?'Numerical and critical criteria met.':'Revise and submit again.'} ${value('quizDirty')==='yes'?'Answers or response have changed: resubmit current answers.':''}`:''}</div><details><summary>Previous attempt log (${state.attempts.length})</summary><ol>${state.attempts.map(a=>`<li>${esc(a.time)}: ${a.score}/8; ${a.passed?'criteria met':'revisit'}${a.revision?' · response saved':''}</li>`).join('')}</ol></details><h2>Respond to feedback</h2>${field('revision','Describe one specific correction or verification and its reason (at least 30 characters).',true)}<button data-action="revision">Save feedback response</button><div id="feedback-revision" class="feedback" role="status">${state.done.assessment?'Independent evidence and response saved.':''}</div></section>`;}
function finish(){return header('Save your evidence.','A final card records your method, reproducible arithmetic, timing or model assumptions, and limitations.')+`<section class="panel">${field('cardMethod','Method and assumptions (30+ characters)',true)}${field('cardCheck','Checked number, units and reproducible calculation (30+ characters)',true)}${field('cardLimit','Material limitation and what evidence would be needed next (30+ characters)',true)}${box('cardCriteria','I compared my card with the rubric and corrected an unsupported claim.')}<details><summary>Self-review rubric</summary><p>Method: name inputs, assumptions and timing. Calculation: trace a result by hand with units and full precision before rounding. Limitations: distinguish hypothetical mechanics from market evidence. Response: identify a specific revision. Prose is self-reviewed; saving does not establish substantive proficiency.</p></details><button data-action="card">Save my evidence card</button><div id="feedback-finish" class="feedback" role="status"></div><ul>${STEPS.map(([id,t])=>`<li>${state.done[id]?'Complete':'To do'}: ${t}</li>`).join('')}</ul><button data-action="export">Export complete chapter record</button></section><section class="panel"><h2>Sources and further consolidation</h2><ul>${SOURCES.map(([t,u])=>`<li><a href="${u}">${t}</a></li>`).join('')}</ul><p>Original synthetic teaching data. Primary references checked 31 October 2026. Learning prototype: pacing and prose rubric need human validation; full screen-reader testing and a learner pilot remain pending.</p><p><a href="../python/?chapter=8#ch8-timing">Optional Python consolidation (+30 minutes)</a>: two standard-library scripts, with separate progress and additional setup time beyond the 30-hour noncoding core.</p><p><a href="../chapter-09/">Continue to Chapter 9 →</a></p></section>`;}
function render(focus=true){const next=location.hash.slice(1)||'start';if(next==='lesson'&&$('#lesson').children.length){$('#lesson').focus();return;}page=next;if(!STEPS.some(s=>s[0]===page))page='start';const i=STEPS.findIndex(s=>s[0]===page);$('#lesson').innerHTML=(LESSONS[page]?practice(page):({start,lab,assessment,finish}[page])())+`<div class="bottom-nav">${i?`<a href="#${STEPS[i-1][0]}">← Previous step</a>`:'<a href="../chapter-07/">← Chapter 7</a>'}${i<7?`<a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]} →</a>`:'<a href="#start">Back to overview ↑</a>'}</div>`;nav();if(focus)$('#lesson').focus();}
document.addEventListener('input',e=>{if(!e.target.matches('[data-save]'))return;const id=e.target.id;state.fields[id]=e.target.type==='checkbox'?(e.target.checked?'yes':''):e.target.value;invalidate(state,id);persist();});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#lesson').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='export'){download('qf-chapter-08-record.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2));$('#announcement').textContent='Chapter 8 record exported.';}
if(action==='setup'){if(value('setup')!=='yes')return feedback('feedback-start','Confirm the setup checklist first.',true);state.done.start=true;persist();location.hash='timing';}
if(action==='practice'){const q=Object.values(PRACTICE).flat().find(q=>q.id===e.target.dataset.id),ok=check(q,value(q.id));state.checked[q.id]=ok;state.practiceAttempts.push({id:q.id,raw:value(q.id),correct:ok,time:new Date().toISOString()});delete state.done[page];persist();feedback('feedback-'+q.id,ok?'Correct. '+q.hint:'Revisit. '+q.hint+' Use the stated units, revise, and check again.',!ok);}
if(action==='save-step'){if(!PRACTICE[page].every(q=>state.checked[q.id]&&check(q,value(q.id)))||value(page+'Reflection').trim().length<30||value(page+'Criteria')!=='yes')return feedback('feedback-step','Check both tasks correctly, write a specific explanation (30+ characters), and confirm your self-review.',true);state.done[page]=true;persist();feedback('feedback-step','Lesson evidence saved. Your prose is self-reviewed against the stated criteria.');}
if(action==='run'){if(value('prediction').trim().length<20)return feedback('feedback-run','Write a prediction with reason,at least20characters,before running.',true);try{if(String(state.fields.cost??10).trim()==='')throw Error('Enter an explicit cost,including0if intended. A blank is not zero.');const cost=Number(state.fields.cost??10),result=backtest(DATA,{costBps:cost});state.runs.push({cost,result,prediction:value('prediction'),time:new Date().toISOString()});state.fields.hand='';state.fields.handVerified='';delete state.done.lab;persist();render(false);feedback('feedback-run','Execution ledger and final exits recorded. Verify the first interval,then change only costs.');}catch(err){feedback('feedback-run',err.message,true);}}
if(action==='hand'){const r=state.runs.at(-1),ok=r&&check({answer:r.result.rows[0].endWealth,tolerance:.011},value('hand'));state.fields.handVerified=ok?'yes':'';delete state.done.lab;persist();feedback('feedback-hand',ok?'Correct:latest first interval verified.':'Use1000×(1−cost/10000)×100/103 for the latest run. Revise and check again.',!ok);}
if(action==='save-lab'){if(!labEvidence(state))return feedback('feedback-lab','Keep current inputs and prediction matched to latest run;compare two cost levels,verify the latest first interval,and write50+character reflection with self-review.',true);state.done.lab=true;persist();feedback('feedback-lab','Fixed-rule sensitivity evidence saved.');}
if(action==='csv'){if(!state.runs.length)return feedback('feedback-lab','Run the fixed rule first.',true);download('qf-chapter-08-all-ledgers.csv','run,cost_bps,signal_date,entry_date,exit_date,position,turnover,gross_return_decimal,start_wealth_gbp,end_wealth_gbp,benchmark_end_gbp,final_exit_cost_gbp,benchmark_exit_cost_gbp\n'+state.runs.flatMap((r,i)=>r.result.rows.map(p=>[i+1,r.cost,p.signalDate,p.entryDate,p.exitDate,p.position,p.turnover,p.grossReturn,p.startWealth,p.endWealth,p.benchmarkEnd,r.result.finalExitCost,r.result.benchmarkExitCost].join(','))).join('\n'),'text/csv');}
if(action==='grade'){const answers=Object.fromEntries(ASSESSMENTS.map(q=>[q.id,value('quiz-'+q.id)]));if(ASSESSMENTS.some(q=>answers[q.id].trim()===''))return feedback('feedback-assessment','Answer all eight questions before checking. No time limit applies.',true);const result=grade(answers);state.attempts.push({...result,answers,time:new Date().toISOString()});state.fields.quizDirty='';state.fields.revision='';delete state.done.assessment;persist();feedback('feedback-assessment',`${result.score}/8. ${result.passed?'Criteria met; now record a feedback response.':'Revise and resubmit; all critical conventions must be correct.'} `+ASSESSMENTS.map(q=>`${q.id}: ${check(q,answers[q.id])?'Correct':'Revisit'} — ${q.hint}`).join(' '),!result.passed);}
if(action==='revision'){const a=state.attempts.at(-1);if(!a||!ASSESSMENTS.every(q=>a.answers[q.id]===value('quiz-'+q.id)))return feedback('feedback-revision','Submit your current answers before saving their feedback response.',true);if(value('revision').trim().length<30)return feedback('feedback-revision','Describe a specific correction or verification (at least 30 characters).',true);a.revision=value('revision');state.fields.quizDirty='';if(a.passed)state.done.assessment=true;persist();feedback('feedback-revision',a.passed?'Feedback response saved. Independent check complete.':'Response saved. Revise answers and resubmit to meet the criteria.');}
if(action==='card'){if(!['cardMethod','cardCheck','cardLimit'].every(id=>value(id).trim().length>=30)||value('cardCriteria')!=='yes')return feedback('feedback-finish','Complete all three 30+ character fields and confirm your self-review.',true);state.done.finish=true;persist();render(false);feedback('feedback-finish',STEPS.every(([id])=>state.done[id])?'Chapter complete. Export your evidence and card for your records.':'Evidence card saved. Use the checklist to complete any missing evidence.');}
});
$('#chapter-select').addEventListener('change',e=>{location.href=e.target.value==='1'?'../index.html':`../chapter-${e.target.value.padStart(2,'0')}/`;});$('#privacy-button').onclick=()=>$('#privacy-dialog').showModal();$('#close-privacy').onclick=()=>$('#privacy-dialog').close();$('#reset-progress').onclick=()=>{if(!confirm('Delete only Chapter 8 browser progress and runs? Other chapters and downloaded files remain.'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();location.hash='start';render();$('#announcement').textContent='Chapter 8 reset.';};window.addEventListener('hashchange',()=>render());render(false);
